exercises.solution:
const compra = 2000;

function precoFinal(centavos, desconto = 10, sacola = 50) {
  const valorDoDesconto = centavos * desconto / 100;
  return Math.round(centavos - valorDoDesconto) + sacola;
}

console.log(`Padrão: R$ ${(precoFinal(compra) / 100).toFixed(2)}`);
console.log(`Promoção: R$ ${(precoFinal(compra, 25) / 100).toFixed(2)}`);
console.log(`Sem desconto nem sacola: R$ ${(precoFinal(compra, 0, 0) / 100).toFixed(2)}`);

